mapper.select:


    inner join sys_user u on u.user_name = twarehouse.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    twarehouse.del_flag = '0'
     and twarehouse.name like concat('%', #{name}, '%')
     and twarehouse.status = #{status}
     and twarehouse.phone  like concat('%', #{phone}, '%')
     and twarehouse.contact_person   like concat('%', #{contactPerson}, '%')
     and twarehouse.role_id = #{roleId}


${params.dataScope}
order by twarehouse.id desc
